class Word{
	constructor(char,x,y,alpha,haveStroke=false){

		this.fadeSpeed=random(1,3);
		this.x=x;
		this.y=y;
		this.char=char;
		this.fadingIn=true;
		this.alpha=alpha;
		this.haveStroke=haveStroke;

	}
	move(){
		this.x+=random(-1,1);
		this.y+=random(-1,1);
	}
	show(){
		if(this.haveStroke){
			 stroke(244, 244, 0, this.alpha); 
			 strokeWeight(2); 
		}else{
			noStroke();
		}
		fill(0,0,0, this.alpha);
		text(this.char,this.x,this.y);
	}
	fade(){
		if (this.fadingIn) {
    this.alpha += this.fadeSpeed; 
    if (this.alpha >= 255) { 
      this.alpha = 255;
      this.fadingIn = false; 
    }
  } else {
    this.alpha -= this.fadeSpeed; 
    if (this.alpha <= 0) { 
      this.alpha = 0;
      this.fadingIn = true; 
    }
  }
	}
}

